SELECT

    (
        (
            COUNT(*) FILTER (
                WHERE "b"."name" = 'Student'
                  AND EXTRACT(YEAR FROM "b"."date"::date) = 2010
            )::numeric
            / NULLIF(COUNT(*) FILTER (WHERE "b"."name" = 'Student'), 0)
        ) * 100
        -
        (
            COUNT(*) FILTER (
                WHERE "b"."name" = 'Student'
                  AND EXTRACT(YEAR FROM "b"."date"::date) = 2011
